//go:build !tinygo

package wide

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"testing"
)

// TestWidegen runs widegen into a temporary folder and makes sure that its
// files are the same, byte for byte, as the generated files of the package.
// It also makes sure that each file with the header of widegen is one that
// widegen writes. The test needs the go command, so it is skipped where a
// test cannot run it, such as wasm. TinyGo does not build it.
func TestWidegen(t *testing.T) {
	if runtime.GOOS == "js" || runtime.GOOS == "wasip1" {
		t.Skip("a test on wasm cannot run the go command")
	}
	goCmd, err := exec.LookPath("go")
	if err != nil {
		t.Skip("the go command is not in PATH")
	}
	dir := t.TempDir()
	cmd := exec.CommandContext(t.Context(), goCmd, "run", "./internal/widegen", "-out", dir)
	// Build widegen for the host, also when the test runs for another
	// GOARCH or with GOEXPERIMENT=simd.
	cmd.Env = append(os.Environ(), "GOOS=", "GOARCH=", "GOEXPERIMENT=", "GOFLAGS=")
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("go run ./internal/widegen: %v\n%s", err, out)
	}
	generated, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]bool{}
	for _, e := range generated {
		want[e.Name()] = true
		g, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			t.Fatal(err)
		}
		c, err := os.ReadFile(e.Name())
		if err != nil {
			t.Errorf("widegen writes %s, and the package does not have it: %v", e.Name(), err)
			continue
		}
		if !bytes.Equal(g, c) {
			t.Errorf("%s differs from the output of widegen. Run go generate ./internal/wide", e.Name())
		}
	}
	files, err := filepath.Glob("*.go")
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range files {
		if !want[name] && hasWidegenHeader(t, name) {
			t.Errorf("%s has the header of widegen, and widegen does not write it", name)
		}
	}
}

// hasWidegenHeader reports whether the first line of the file name is the
// header of widegen.
func hasWidegenHeader(t *testing.T, name string) bool {
	t.Helper()
	b, err := os.ReadFile(name)
	if err != nil {
		t.Fatal(err)
	}
	return bytes.HasPrefix(b, []byte("// Code generated by widegen."))
}
